/**
 * 把 locale/*.json 编译进 client.js。
 *
 * 浏览器半通过 `window.__ModuleLoader__.load` 加载，运行时无法读取 JSON 文件，
 * 因此字典在构建期以字面量形式内联。修改译文只需改 locale/*.json，再执行：
 *   node .github/scripts/build-locales.mjs
 * 或 `npm run build:locales`。CI 会校验内联结果与 JSON 一致。
 */
import { readFile, writeFile, readdir } from 'node:fs/promises'
import { join, dirname, basename } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..', '..')
const clientPath = join(root, 'client.js')

/**
 * JSON 文件名 → 内联变量名，以及该字典接受的 DSH 语言 id。
 *
 * 宿主（dsh-client-locale）内置的语言 id 只有 `zh` 和 `en`；`zh` 表示简体中文。
 * 因此简体字典必须同时注册在 `zh` 下，否则中文界面的 `t()` 找不到词条、会回退到
 * 英文或直接显示 key。其它语言用各自的 BCP 47 id，并且都可以通过下面的别名规则命中。
 */
const TARGETS = [
  { file: 'zh-cn.json', variable: 'zhCN', ids: ['zh', 'zh-CN', 'zh-Hans'], label: '简体中文' },
  { file: 'zh-tw.json', variable: 'zhTW', ids: ['zh-TW', 'zh-Hant', 'zh-HK'], label: '繁體中文' },
  { file: 'ja.json', variable: 'ja', ids: ['ja', 'ja-JP'], label: '日本語' },
  { file: 'en.json', variable: 'en', ids: ['en', 'en-US', 'en-GB'], label: 'English' },
]

const BEGIN = '    // >>> LOCALES BEGIN (generated by .github/scripts/build-locales.mjs)'
const END = '    // <<< LOCALES END'

const dictionaries = []
for (const target of TARGETS) {
  const raw = JSON.parse(await readFile(join(root, 'locale', target.file), 'utf8'))
  // meta 只供插件清单展示，不进入运行时字典
  const { meta, ...copy } = raw
  dictionaries.push({ ...target, meta, copy })
}

// 键集合必须完全一致，否则某些语言会缺字
const reference = Object.keys(dictionaries[dictionaries.length - 1].copy).sort()
for (const dictionary of dictionaries) {
  const keys = Object.keys(dictionary.copy).sort()
  const missing = reference.filter((key) => !keys.includes(key))
  const extra = keys.filter((key) => !reference.includes(key))
  if (missing.length || extra.length) {
    console.error(`locale/${dictionary.file} 键不一致：缺少 ${missing.join(', ') || '无'}；多出 ${extra.join(', ') || '无'}`)
    process.exit(1)
  }
}

/** 生成一段缩进整齐的对象字面量。 */
function literal(variable, copy) {
  const lines = Object.entries(copy).map(([key, value]) => `      ${JSON.stringify(key)}: ${JSON.stringify(value)},`)
  return [`    const ${variable} = {`, ...lines, '    }'].join('\n')
}

const generated = [
  '    // Dictionaries are generated from locale/*.json; edit the JSON, then run',
  '    // `npm run build:locales`. Never edit this block by hand.',
  ...dictionaries.flatMap((dictionary) => [literal(dictionary.variable, dictionary.copy), '']),
  '    // Every id the host may report for one dictionary. The host ships `zh`/`en`;',
  '    // regional and script variants are listed so a browser-derived tag still matches.',
  '    const LOCALES = {',
  ...dictionaries.flatMap((dictionary) =>
    dictionary.ids.map((id) => `      ${JSON.stringify(id)}: ${dictionary.variable},`),
  ),
  '    }',
  '',
  '    // Ids registered as namespace dictionaries. `zh` and `en` are the host built-ins,',
  '    // so they must be present or a Chinese UI silently falls back to English.',
  '    const LOCALE_IDS = [',
  ...dictionaries.map((dictionary) => `      ${JSON.stringify(dictionary.ids[0])},`),
  '    ]',
  '',
  '    /** Canonical dictionary key for an active locale id, or undefined when unsupported. */',
  '    function resolveLocale(activeLocale) {',
  '      if (LOCALES[activeLocale]) return activeLocale',
  '      const tag = String(activeLocale || "").toLowerCase().replace(/_/g, "-")',
  '      if (!tag) return undefined',
  '      if (LOCALES[tag]) return tag',
  '      // Primary subtag, then script/region hints for Chinese.',
  '      const primary = tag.split("-")[0]',
  '      if (primary === "zh") {',
  '        if (tag.includes("hant") || tag.includes("tw") || tag.includes("hk") || tag.includes("mo")) return "zh-TW"',
  '        return "zh"',
  '      }',
  '      if (LOCALES[primary]) return primary',
  '      return undefined',
  '    }',
  '',
  '    /** Pick the dictionary for the active locale, falling back to English. */',
  '    function dictionaryFor(activeLocale) {',
  '      return LOCALES[resolveLocale(activeLocale)] || LOCALES.en',
  '    }',
].join('\n')

const source = await readFile(clientPath, 'utf8')
const start = source.indexOf(BEGIN)
const end = source.indexOf(END)
if (start < 0 || end < 0) {
  console.error('client.js 中找不到 LOCALES 生成标记，请确认标记没有被删除')
  process.exit(1)
}
const next = `${source.slice(0, start)}${BEGIN}\n${generated}\n${source.slice(end)}`
await writeFile(clientPath, next, 'utf8')

// 清理已废弃的旧文件（旧的 locale/zh.json 只有 meta）
const existing = await readdir(join(root, 'locale'))
const stale = existing.filter((name) => name.endsWith('.json') && !TARGETS.some((target) => target.file === name))
if (stale.length) {
  console.log(`提示：locale/ 下存在未纳入构建的文件：${stale.join(', ')}`)
}

console.log(`已编译 ${dictionaries.length} 种语言：${dictionaries.map((dictionary) => dictionary.ids[0]).join(', ')}`)
console.log(`注册的 locale id：${dictionaries.flatMap((dictionary) => dictionary.ids).join(', ')}`)
console.log(`键数量：${reference.length}`)
console.log(`meta 标题：${dictionaries.map((dictionary) => `${dictionary.ids[0]}=${dictionary.meta?.title || '(缺)'}`).join(', ')}`)
